// 최신 레슨 데이터에서 다음 회차 계산
const latestLesson = $input.first().json;

// 현재 회차 가져오기 (Title 필드: '회차 ')
const currentSessionStr = latestLesson.properties['회차 ']?.title?.[0]?.plain_text || '106';
const currentSession = parseInt(currentSessionStr, 10);
const nextSession = currentSession + 1;

// 최신 레슨 날짜 체크 (시간대 영향 제거)
const lessonDateRaw = latestLesson.properties['수업 날짜']?.date?.start || '';
const lessonDateStr = lessonDateRaw.substring(0, 10); // "yyyy-MM-dd"만 추출
const lessonDate = new Date(lessonDateStr + 'T12:00:00'); // 시간대 문제 방지
const today = new Date($now.setZone('Asia/Bangkok').toFormat('yyyy-MM-dd') + 'T12:00:00');

// 최신 레슨이 아직 미래면 스킵 (연기된 경우)
if (lessonDate >= today) {
  return []; // 빈 배열 반환 → 워크플로우 중단
}

// 10의 배수인지 체크 (110, 120, 130...)
const isTenMultiple = nextSession % 10 === 0;
const fromSession = isTenMultiple ? nextSession + 1 : null;
const toSession = isTenMultiple ? nextSession + 10 : null;

// 다음 목요일 계산 (방콕 시간대)
const todayLuxon = $now.setZone('Asia/Bangkok');
const dayOfWeek = todayLuxon.weekday; // 1=월, 4=목, 7=일
let daysUntilThursday = 4 - dayOfWeek;
if (daysUntilThursday <= 0) daysUntilThursday += 7;
const nextThursday = todayLuxon.plus({ days: daysUntilThursday });

// ISO 날짜 형식
const lessonDateNew = nextThursday.toFormat('yyyy-MM-dd');

return {
  nextSession: nextSession,
  lessonDate: lessonDateNew,
  lessonTime: "17:00",
  location: "포탈라이",
  status: "정상",
  lessonType: "일반",
  isTenMultiple: isTenMultiple,
  fromSession: fromSession,
  toSession: toSession
};

// 방콕 시간대로 2일 후 날짜 계산
const today = $now.setZone('Asia/Bangkok');
const twoDaysLater = today.plus({ days: 2 }).toFormat('yyyy-MM-dd');

// 레슨 데이터
const lesson = $input.first().json;
const props = lesson.properties;

// 레슨 날짜 (시간대 제거, yyyy-MM-dd만 추출)
const lessonDateStr = (props['수업 날짜']?.date?.start || '').substring(0, 10);

// 2일 후 레슨인지 확인
const isTwoDaysLater = twoDaysLater === lessonDateStr;

// 장소 확인 (포탈라이만 해당, 필드레슨 제외)
const location = props['수업 장소']?.select?.name || '포탈라이';
const isPortaLai = location === '포탈라이';

// 조건 미충족 시 빈 배열 반환 (워크플로우 중단)
if (!isTwoDaysLater || !isPortaLai) {
  return [];
}

// 날짜 컴포넌트 추출
const [year, month, day] = lessonDateStr.split('-');

// 태국어 요일 변환 (시간대 문제 방지)
const lessonDate = new Date(lessonDateStr + 'T12:00:00');
const thaiDays = ['วันอาทิตย์', 'วันจันทร์', 'วันอังคาร', 'วันพุธ', 'วันพฤหัสบดี', 'วันศุกร์', 'วันเสาร์'];
const dayOfWeek = thaiDays[lessonDate.getDay()];

// 날짜 포맷 (DD/MM/YYYY) - 문자열에서 직접 추출
const formattedDate = `${day}/${month}/${year}`;

// 장소 태국어
const locationTh = 'โปรทาลัย';

// 상태 확인
const status = props['상태']?.select?.name || '정상';

// 타석 번호 확인
const bayNumber = props['타석 번호']?.rich_text?.[0]?.plain_text || '';

// 회차
const session = props['회차 ']?.title?.[0]?.plain_text || '';

return {
  pageId: lesson.id,
  session: session,
  lessonDate: lessonDateStr,
  formattedDate: formattedDate,
  dayOfWeek: dayOfWeek,
  location: location,
  locationTh: locationTh,
  status: status,
  bayNumber: bayNumber,
  hasBayNumber: bayNumber.length > 0,
  isNormal: status === '정상'
};

