const lesson = $input.first().json;
const props = lesson.properties;

// 날짜 파싱 (시간대 영향 제거)
const lessonDateRaw = props['수업 날짜']?.date?.start || '';
const lessonDateStr = lessonDateRaw.substring(0, 10); // "yyyy-MM-dd"만 추출
const [year, month, day] = lessonDateStr.split('-');
const lessonDate = new Date(lessonDateStr + 'T12:00:00'); // 요일 계산용

// 한국어/태국어 요일
const koDays = ['일요일', '월요일', '화요일', '수요일', '목요일', '금요일', '토요일'];
const thDays = ['วันอาทิตย์', 'วันจันทร์', 'วันอังคาร', 'วันพุธ', 'วันพฤหัสบดี', 'วันศุกร์', 'วันเสาร์'];
const dayOfWeekKo = koDays[lessonDate.getDay()];
const dayOfWeekTh = thDays[lessonDate.getDay()];

// 날짜 포맷 (문자열에서 직접 추출)
const formattedDateKo = `${year}-${month}-${day}`;
const formattedDateTh = `${day}/${month}/${year}`;

// 장소
const location = props['수업 장소']?.select?.name || '포탈라이';
const locationTh = location === '포탈라이' ? 'โปรทาลัย' : location;

// 상태
const status = props['상태']?.select?.name || '';

// 회차
const session = props['회차 ']?.title?.[0]?.plain_text || '';

// 파일 유무 확인 (영수증)
const hasReceipt = props['파일']?.files?.length > 0;

// 10회 단위 계산 (레슨비 범위)
const currentSession = parseInt(session, 10) || 0;
let tenStart, tenEnd;

if (currentSession % 10 === 0) {
  // 10의 배수 (110, 120...): 다음 10회 단위
  tenStart = currentSession + 1;
  tenEnd = currentSession + 10;
} else {
  // 나머지 (111-119...): 현재 속한 10회 단위
  tenStart = Math.floor((currentSession - 1) / 10) * 10 + 1;
  tenEnd = tenStart + 9;
}

// 상태별 처리
const isCancelled = status === '취소';
const isChanged = status === '변경';
const needsNotification = isCancelled || isChanged;

return {
  pageId: lesson.id,
  session: session,
  lessonDate: lessonDateStr,
  formattedDateKo: formattedDateKo,
  formattedDateTh: formattedDateTh,
  dayOfWeekKo: dayOfWeekKo,
  dayOfWeekTh: dayOfWeekTh,
  location: location,
  locationTh: locationTh,
  status: status,
  isCancelled: isCancelled,
  isChanged: isChanged,
  needsNotification: needsNotification,
  hasReceipt: hasReceipt,
  tenStart: tenStart,
  tenEnd: tenEnd
};

